//! Alias addresses: `<site>-<5 letters and digits>`, from the site the
//! alias was made for, or 8 letters and digits when there is none.
//!
//! Bitwarden's addy.io forwarder says the site in its description:
//! "Website: www.expedia.co.uk. Generated by Bitwarden." The site's own
//! name is the label before its public suffix, so that and expedia.com and
//! secure.expedia.com all make `expedia`.
use ring::rand::{SecureRandom, SystemRandom};

const ALPHABET: &[u8] = b"abcdefghijklmnopqrstuvwxyz0123456789";

/// Second-level labels that are part of a country's suffix (co.uk, com.au).
const SECOND_LEVEL: &[&str] = &["co", "com", "net", "org", "gov", "ac", "edu", "ne", "or"];

/// The site's name from Bitwarden's description, if it has one.
pub fn site(description: &str) -> Option<String> {
    let rest = description.split_once("Website: ")?.1;
    let host = rest.split([' ', '/']).next()?.trim_end_matches('.').to_lowercase();
    let labels: Vec<&str> = host.split('.').filter(|l| !l.is_empty()).collect();
    let name = match labels.as_slice() {
        [] => return None,
        [one] => *one,
        [.., second, last] if last.len() == 2 && SECOND_LEVEL.contains(second) && labels.len() >= 3 => {
            labels[labels.len() - 3]
        }
        [.., name, _] => *name,
    };
    let clean: String = name.chars().filter(|c| c.is_ascii_alphanumeric() || *c == '-').take(20).collect();
    let clean = clean.trim_matches('-').to_string();
    (!clean.is_empty()).then_some(clean)
}

pub fn random(len: usize) -> String {
    let mut bytes = vec![0u8; len];
    SystemRandom::new().fill(&mut bytes).expect("the system's random source");
    bytes.iter().map(|b| ALPHABET[*b as usize % ALPHABET.len()] as char).collect()
}

/// A new alias's part before the @.
pub fn local_part(site: Option<&str>) -> String {
    match site {
        Some(site) => format!("{site}-{}", random(5)),
        None => random(8),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_site_is_its_own_name() {
        let d = |host: &str| format!("Website: {host}. Generated by Bitwarden.");
        assert_eq!(site(&d("expedia.com")).as_deref(), Some("expedia"));
        assert_eq!(site(&d("www.expedia.co.uk")).as_deref(), Some("expedia"));
        assert_eq!(site(&d("secure.Expedia.com")).as_deref(), Some("expedia"));
        assert_eq!(site(&d("my-bank.com.au")).as_deref(), Some("my-bank"));
        assert_eq!(site(&d("localhost")).as_deref(), Some("localhost"));
        assert_eq!(site("Generated by Bitwarden."), None);
        assert_eq!(site(""), None);
    }

    #[test]
    fn addresses_are_site_dash_five_or_eight() {
        let a = local_part(Some("expedia"));
        assert!(a.starts_with("expedia-") && a.len() == "expedia-".len() + 5, "{a}");
        let b = local_part(None);
        assert_eq!(b.len(), 8);
        assert!(a.chars().chain(b.chars()).all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-'));
        assert_ne!(random(8), random(8));
    }
}
